/**
 * loadDisplaySubjectArea against the extension host's golden output.
 *
 * The golden files (test/fixtures/golden) are generated by the repo-root test
 * test/unit/displayDomainGolden.test.ts, which drives the real extension host
 * over the same fixture projects. This proves the one-call core pipeline
 * builds the same DisplaySubjectArea the extension posts to its webview — minus
 * the editor-only `templates`, `manifestModels`, `existingModels` and
 * `relationshipsInDiagramFile` / `inDiagramFile` — and
 * fails bad domains with the same messages.
 *
 * Domain paths are passed relative to each fixture project, the way a host
 * reading from a repository would name them, so the golden messages are
 * compared with their `<root>/` prefix removed.
 */

import { describe, it, expect } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';

import { loadDisplaySubjectArea } from '../../src/loadDisplayDomain';
import { SubjectAreaFileError, SubjectAreaValidationError } from '../../src/domain';
import { STORAGE_EQUIVALENCE_ROWS, normaliseStorageRows, type StorageEquivalenceRow } from '../../src/storageEquivalence';
import { dbmlStorageReader } from '../../src/dbml/index';
import { DIAGRAM_EXPORT_FILE_EXTENSIONS, exportDiagram } from '../../src/exportDiagram';
import type { DisplaySubjectArea } from '../../src/types/display';
import { readDbmlEverywhere, readDbmlRich } from '../exportParsers';

/** The sentence the extension's not-a-diagram page ends with (§1.8), which core does not write. */
const REOPEN_AS_TEXT = 'To edit it as text, right-click the tab and choose Reopen Editor With… > Text Editor.';
const FIXTURES = path.resolve(__dirname, '../fixtures');
const GOLDEN_DIR = path.join(FIXTURES, 'golden');

const SUBJECT_AREA_CASES: Record<string, string> = {
  showcase: '.erd-studio/silver/showcase.json',
  'v4-inline': '.erd-studio/bronze/orders.json',
  'missing-model': '.erd-studio/silver/partial.json',
  'no-layers': '.erd-studio/gold/accounts.json',
  'missing-positions': '.erd-studio/silver/showcase.json',
  'library-relationships': '.erd-studio/gold/sales.json',
  'v4-nameless-column': '.erd-studio/silver/orders.json',
  'composite-and-self': '.erd-studio/gold/vault.json',
  'data-type-alias': '.erd-studio/silver/orders.json',
  'domain-one-to-many': '.erd-studio/gold/sales.json',
  'duplicate-key': '.erd-studio/silver/orders.json',
  'rationale-and-meta': '.erd-studio/silver/ledger.json',
};

const ERROR_CASES: Record<string, string> = {
  legacy: '.erd-studio/silver/legacy.json',
  hybrid: '.erd-studio/silver/hybrid.json',
  future: '.erd-studio/silver/future.json',
  noversion: '.erd-studio/silver/noversion.json',
  array: '.erd-studio/silver/array.json',
  empty: '.erd-studio/silver/empty.json',
  invalid: '.erd-studio/silver/invalid.json',
  badlayer: '.erd-studio/platinum/badlayer.json',
  // Native DBML storage: a DBML diagram that does not parse, one from a
  // newer schema, one with git conflict markers, a table file passed as the
  // diagram, and a diagram where the 1.9 pre-release kept it. Read with the
  // DBML readers.
  'dbml-syntax': '.erd-studio/silver/diagrams/dbml-syntax.dbml',
  'dbml-future': '.erd-studio/silver/diagrams/dbml-future.dbml',
  'dbml-conflict': '.erd-studio/silver/diagrams/dbml-conflict.dbml',
  'dbml-not-a-diagram': '.erd-studio/silver/tables/silver/dim_customer.dbml',
  'dbml-legacy': '.erd-studio/gold/old.dbml',
};

/**
 * The DBML twins (packages/core/test/fixtures/dbml/<case>): the same projects
 * stored as native DBML, in the layer-first tree (`<layer>/tables/<schema>/`,
 * `<layer>/relationships/<layer>.dbml`, `<layer>/diagrams/`), as Convert
 * writes them. Each draws what its YAML case's golden draws once both go
 * through **only the §2.8 rows it lists** (§9.2: a row a case does not list
 * must not change that case), and each listed row is needed (drop it and the
 * two differ). The full comparator (D24, plus the schema row) agrees as well.
 *
 * These compare the Display shape. Rows that touch only the Unified shape
 * (composite-and-self's lone `fk_lonely` key and raw Ref spellings, the
 * library-relationships domain copy) show there, with the host.
 */
const DBML_TWIN_CASES: Record<string, {
  domainPath: string;
  rows: Partial<Record<StorageEquivalenceRow, string>>;
  /** The schema Convert gave each table its YAML file names none (`convertSchemaFallback`): its schema folder. */
  schemas?: Record<string, string>;
}> = {
  showcase: {
    domainPath: '.erd-studio/silver/diagrams/showcase.dbml',
    rows: {
      relationshipOrder: 'the diagram file held the relationships in its own order; a relationships file keeps its Refs sorted',
      emptyAnnotations: 'the JSON file holds "annotations": []; a diagram with no Note blocks reads back with no list',
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
      tableLayers: 'a DBML table records the layer of its file; a YAML table has none',
      convertSchemaFallback: 'fct_order.yml names no schema and sits at the top of the library: Convert files it in silver/tables/public/',
    },
    schemas: { fct_order: 'public' },
  },
  'composite-and-self': {
    domainPath: '.erd-studio/gold/diagrams/vault.dbml',
    rows: {
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
      tableLayers: 'a DBML table records the layer of its file; a YAML table has none',
      convertSchemaFallback: 'the YAML files name no schema: Convert takes their library folder, logical-models/gold/',
    },
    schemas: { employee: 'gold', pit_customer: 'gold', sat_customer: 'gold' },
  },
  'missing-positions': {
    domainPath: '.erd-studio/silver/diagrams/showcase.dbml',
    rows: {
      relationshipOrder: 'the diagram file held the relationships in its own order; a relationships file keeps its Refs sorted',
      emptyAnnotations: 'the JSON file holds "annotations": []; a diagram with no Note blocks reads back with no list',
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
      tableLayers: 'a DBML table records the layer of its file; a YAML table has none',
      convertSchemaFallback: 'fct_order.yml names no schema and sits at the top of the library: Convert files it in silver/tables/public/',
    },
    schemas: { fct_order: 'public' },
  },
  'missing-model': {
    domainPath: '.erd-studio/silver/diagrams/partial.dbml',
    rows: {
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
      tableLayers: 'a DBML table records the layer of its file; a YAML table has none',
    },
  },
  // Convert's own output for missing-model (D26/D27): dim_missing, broken (left as YAML: it does not
  // parse) and nameless (left as YAML: no name) are named in erd_unlinked_tables, and the diagram's two
  // relationships from tables with no DBML file are its pending lines. No exception: it draws what the
  // JSON diagram drew, broken's YAML load error included.
  'missing-model-converted': {
    domainPath: '.erd-studio/silver/diagrams/partial.dbml',
    rows: {
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
      tableLayers: 'a DBML table records the layer of its file; a YAML table has none',
    },
  },
  'library-relationships': {
    domainPath: '.erd-studio/gold/diagrams/sales.dbml',
    rows: {
      oneToMany: 'a library one-to-many (1.6.6 / 1.6.7) is stored canonically, as fct_order many-to-one',
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
      tableLayers: 'a DBML table records the layer of its file; a YAML table has none',
    },
  },
};

/** A twin compared with another case's golden. */
const GOLDEN_OF: Record<string, string> = { 'missing-model-converted': 'missing-model' };

/**
 * What a twin cannot hold, beyond the §2.8 rows, applied to the YAML golden
 * before the comparison, each with its one-line reason.
 */
const DBML_TWIN_EXCEPTIONS: Record<string, (expected: Record<string, unknown>) => void> = {
  // A Ref is drawn only from a readable DBML owner (§2.4): dim_missing has no
  // file and broken.dbml does not parse, so the diagram file's two
  // relationships from them have no DBML home; and broken's load error is a
  // DBML one (kind, line and code), not YAML's.
  'missing-model': (expected) => {
    expected.relationships = [];
    const models = expected.models as Array<Record<string, unknown>>;
    const broken = models.find((m) => m.name === 'broken')!;
    broken.loadError = { kind: 'dbmlSyntax', line: 5, code: '1005' };
  },
};

const LINE_COLUMN = / \(line \d+ column \d+\)/g;

function readGolden(file: string): { type: string; payload: Record<string, unknown> } {
  return JSON.parse(fs.readFileSync(path.join(GOLDEN_DIR, file), 'utf-8'));
}

/** A readFile over one fixture project: relative paths, ENOENT as null. */
function fsReadFile(root: string) {
  return async (p: string): Promise<string | null> => {
    try {
      return fs.readFileSync(path.join(root, p), 'utf-8');
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  };
}

describe('loadDisplaySubjectArea matches the extension host golden output', () => {
  describe.each(Object.entries(SUBJECT_AREA_CASES))('%s', (name, domainPath) => {
    it('builds the posted DisplaySubjectArea, without the editor-only fields', async () => {
      const root = path.join(FIXTURES, name);
      const domain = await loadDisplaySubjectArea({
        domainPath,
        readFile: fsReadFile(root),
        readOnly: false,
        warn: () => {},
      });

      const expected = { ...readGolden(`${GOLDEN_OF[name] ?? name}.host.json`).payload };
      delete expected.templates;
      delete expected.manifestModels;
      delete expected.existingModels;
      // The editor notes which relationships the diagram file holds (the Remove confirmation's); core does not.
      delete expected.relationshipsInDiagramFile;
      expected.relationships = (expected.relationships as Array<Record<string, unknown>>).map(({ inDiagramFile: _own, ...r }) => r);

      // postMessage serialises the payload, which drops undefined values.
      expect(JSON.parse(JSON.stringify(domain))).toEqual(expected);
    });
  });

  describe.each(Object.entries(ERROR_CASES))('errors/%s', (name, domainPath) => {
    it('rejects with the golden message and the matching error class', async () => {
      const golden = readGolden(`errors.${name}.host.json`).payload as {
        message: string; kind?: string; fileProblem?: 'empty' | 'syntax'; line?: number; column?: number;
      };
      const isDbml = domainPath.endsWith('.dbml');
      let caught: unknown;
      try {
        await loadDisplaySubjectArea({
          domainPath,
          readFile: fsReadFile(path.join(FIXTURES, 'errors')),
          readOnly: false,
          warn: () => {},
          ...(isDbml ? { dbml: dbmlStorageReader } : {}),
        });
      } catch (err) {
        caught = err;
      }
      // The host tags SubjectAreaFileError failures with kind 'domain-file'.
      expect(caught).toBeInstanceOf(golden.kind === 'domain-file' ? SubjectAreaFileError : SubjectAreaValidationError);
      // An empty or invalid file (#186): the host words its own sentence from
      // core's reason and location, so those are what must agree.
      if (golden.fileProblem) {
        const err = caught as SubjectAreaFileError;
        expect(err.reason).toBe(golden.fileProblem === 'empty' ? 'empty' : isDbml ? 'invalid-dbml' : 'invalid-json');
        expect({ line: err.line, column: err.column }).toEqual({ line: golden.line, column: golden.column });
        return;
      }
      const message = (caught as Error).message.replace(LINE_COLUMN, '');
      // The extension's not-a-diagram page adds how to reopen the file as text (§1.8); core's own text has no such sentence.
      const expected = golden.message.split('<root>/').join('').replace(` ${REOPEN_AS_TEXT}`, '');
      // The host's "can't read this diagram's file" screen (#261, `kind: 'invalid'`) ends core's
      // reason with exactly one full stop; core's own sentence may have none.
      expect(golden.kind === 'invalid' ? `${message.replace(/\.\s*$/, '')}.` : message).toBe(expected);
    });
  });

  describe.each(Object.entries(DBML_TWIN_CASES))('the DBML twin of %s', (name, { domainPath, rows, schemas = {} }) => {
    const listed = Object.keys(rows) as StorageEquivalenceRow[];
    const options = { schemaFallback: (table: string) => schemas[table] };
    const read = async (): Promise<{ twin: Record<string, unknown>; expected: Record<string, unknown> }> => {
      const domain = await loadDisplaySubjectArea({
        domainPath,
        readFile: fsReadFile(path.join(FIXTURES, 'dbml', name)),
        readOnly: false,
        warn: () => {},
        dbml: dbmlStorageReader,
      });
      expect(domain.schemaVersion).toBe(7);
      const expected = { ...readGolden(`${GOLDEN_OF[name] ?? name}.host.json`).payload };
      delete expected.templates;
      delete expected.manifestModels;
      delete expected.existingModels;
      // The editor notes which relationships the diagram file holds (the Remove confirmation's); core does not.
      delete expected.relationshipsInDiagramFile;
      expected.relationships = (expected.relationships as Array<Record<string, unknown>>).map(({ inDiagramFile: _own, ...r }) => r);
      DBML_TWIN_EXCEPTIONS[name]?.(expected);
      return { twin: JSON.parse(JSON.stringify(domain)), expected };
    };

    it(`draws what the YAML golden draws through only its listed §2.8 rows (${listed.join(', ')})`, async () => {
      const { twin, expected } = await read();
      expect(normaliseStorageRows(twin, listed, options)).toEqual(normaliseStorageRows(expected, listed, options));
      const full = [...STORAGE_EQUIVALENCE_ROWS, 'convertSchemaFallback'] as StorageEquivalenceRow[];
      expect(normaliseStorageRows(twin, full, options)).toEqual(normaliseStorageRows(expected, full, options));
    });

    it.each(listed)('needs the row it lists: %s', async (row) => {
      const { twin, expected } = await read();
      const without = listed.filter((r) => r !== row);
      expect(normaliseStorageRows(twin, without, options)).not.toEqual(normaliseStorageRows(expected, without, options));
    });
  });

  it.each([
    ['with no name: key', null],
    ['empty', ''],
  ])('a DBML diagram member whose YAML file is %s is not called a YAML table: it is drawn as missing, as the plan says', async (_label, namelessText) => {
    const root = path.join(FIXTURES, 'dbml', 'missing-model-converted');
    const read = fsReadFile(root);
    const warnings: string[] = [];
    await loadDisplaySubjectArea({
      domainPath: '.erd-studio/silver/diagrams/partial.dbml',
      readFile: async (p) => (namelessText !== null && p.endsWith('/nameless.yml') ? namelessText : read(p)),
      readOnly: false,
      warn: (m) => warnings.push(m),
      dbml: dbmlStorageReader,
    });
    const mixed = warnings.filter((w) => w.includes('is a YAML table'));
    // broken.yml is a table that does not parse: Convert leaves it, and editing waits for it.
    expect(mixed).toEqual([
      'Table "broken" is a YAML table (.erd-studio/logical-models/broken.yml); the DBML diagram shows it, but run ERD Studio: Convert Project to DBML '
        + 'before editing its relationships (fix the file first if Convert leaves it as it is)',
    ]);
    // Its parse error still follows the mixed-state warning.
    expect(warnings.indexOf(mixed[0])).toBeLessThan(warnings.findIndex((w) => w.startsWith('Failed to read model "broken"')));
  });
});

/**
 * Sample rows (D37): the sample-rows twin (packages/core/test/fixtures/dbml/sample-rows) holds a
 * nested `records` block in every form a table file may hold one: a full list (dim_product, with
 * empty fields in later rows and a negative value), no list (dim_customer: every column, in order),
 * one name (dim_region, its key), an empty list (dim_channel, never shown) and a list beside an Enum
 * whose values it names (fct_order_line, whose keys join the dimensions'). Core draws it without rows
 * by default (`<…>.display.json`, which every older core would also draw) and with them when asked
 * (`<…>.rows.display.json`). The plain DBML and Mermaid exports never carry rows: their goldens are
 * the same with and without them. The rich DBML export writes them (`<…>.rich.dbml`): the rows join
 * and fit their types, so every 9.1+ parser reads the golden with no data lint either.
 *
 * Goldens (packages/core/test/fixtures/golden/sample-rows.shop.*): regenerate with UPDATE_GOLDEN=1
 * for an intended change.
 */
describe('sample rows (the sample-rows twin)', () => {
  const UPDATE = process.env.UPDATE_GOLDEN === '1';
  const load = (readSampleData: boolean): Promise<DisplaySubjectArea> => loadDisplaySubjectArea({
    domainPath: '.erd-studio/gold/diagrams/shop.dbml',
    readFile: fsReadFile(path.join(FIXTURES, 'dbml', 'sample-rows')),
    readOnly: false,
    warn: () => {},
    dbml: dbmlStorageReader,
    ...(readSampleData ? { readSampleData } : {}),
  });
  const golden = (file: string, text: string): void => {
    const full = path.join(GOLDEN_DIR, file);
    if (UPDATE) fs.writeFileSync(full, text);
    expect(text).toBe(fs.readFileSync(full, 'utf-8'));
  };

  it('without readSampleData: no table carries rows (sample-rows.shop.display.json)', async () => {
    const display = await load(false);
    expect(display.models.filter((m) => 'sampleData' in m)).toEqual([]);
    golden('sample-rows.shop.display.json', JSON.stringify(display, null, 2) + '\n');
  });

  it('with readSampleData: each table with rows carries them, and nothing else changes (sample-rows.shop.rows.display.json)', async () => {
    const display = await load(true);
    expect(display.models.filter((m) => m.sampleData !== undefined).map((m) => m.name).sort()).toEqual(['dim_customer', 'dim_product', 'dim_region', 'fct_order_line']);
    const without = JSON.parse(JSON.stringify(display)) as DisplaySubjectArea;
    for (const m of without.models) delete m.sampleData;
    expect(JSON.stringify(without, null, 2) + '\n').toBe(fs.readFileSync(path.join(GOLDEN_DIR, 'sample-rows.shop.display.json'), 'utf-8'));
    golden('sample-rows.shop.rows.display.json', JSON.stringify(display, null, 2) + '\n');
  });

  it.each(['dbml', 'mermaid'] as const)('the %s export holds no row, with rows read or not', async (format) => {
    const withRows = exportDiagram(await load(true), format);
    expect(withRows).toBe(exportDiagram(await load(false), format));
    golden(`sample-rows.shop.${DIAGRAM_EXPORT_FILE_EXTENSIONS[format]}`, withRows);
    for (const value of ['Blue widget', 'Harbour Stores', 'R-NORTH', 'order_status.shipped', '-0.25']) expect(withRows).not.toContain(value);
  });

  it('the rich DBML export writes the rows at the end of each Table (sample-rows.shop.rich.dbml), with no data lint in any 9.1+ parser', async () => {
    const rich = exportDiagram(await load(true), 'dbml-rich');
    golden('sample-rows.shop.rich.dbml', rich);
    // Strict, as every rich golden is: no error, warning or lint info, data lints included.
    const read = readDbmlRich(rich, { infos: 'none' });
    expect(read.records?.map((r) => [r.table, r.columns, r.rows.length])).toEqual([
      ['dim_product', ['product_key', 'product_name', 'list_price', 'price_change', 'is_active', 'launched_on'], 3],
      // `records {`: written with its list, every column in order.
      ['dim_customer', ['customer_key', 'customer_name', 'segment'], 3],
      ['fct_order_line', ['order_line_id', 'product_key', 'customer_key', 'quantity', 'status'], 3],
      ['dim_region', ['region_code'], 2],
    ]);
    // An enum reference is written as text (the last segment), an empty field as null.
    expect(read.records?.find((r) => r.table === 'fct_order_line')?.rows.map((row) => row[4][0])).toEqual(['shipped', 'returned', null]);
    expect(rich).not.toContain('order_status.shipped');
    // An empty list (dim_channel) gives no block.
    expect(rich.match(/^ {2}records \(/gm)).toHaveLength(4);
  });

  it('the rich DBML export without rows is the same text without its records blocks', async () => {
    const withRows = exportDiagram(await load(true), 'dbml-rich');
    const without = exportDiagram(await load(false), 'dbml-rich');
    expect(without).not.toMatch(/^ *records \b/m);
    expect(withRows.replace(/\n\n {2}records \([^\n]*\{\n(?: {4}[^\n]*\n)*? {2}\}(?=\n\})/g, '')).toBe(without);
  });

  it('the DBML export reads alike in every pinned parser, old ones included', async () => {
    const read = readDbmlEverywhere(exportDiagram(await load(true), 'dbml'));
    expect(read.tables.map((t) => t.name)).toEqual(['dim_product', 'dim_customer', 'fct_order_line', 'dim_region', 'dim_channel']);
  });
});
